-- Contrôle après application de 0114_contenu.sql (lecture seule) : chaque ligne doit rendre « oui ».
select label, case when ok then 'oui' else 'NON' end as ok from (values
 ('six tables contenu_* présentes', (select count(*) = 6 from pg_class where relnamespace = 'public'::regnamespace and relkind = 'r' and relname in ('contenu_lignes','contenu_comptes','contenu_posts','contenu_mesures','contenu_suspensions','contenu_idees'))),
 ('RLS active sur les six tables', (select count(*) = 6 and bool_and(relrowsecurity) from pg_class where relnamespace = 'public'::regnamespace and relname in ('contenu_lignes','contenu_comptes','contenu_posts','contenu_mesures','contenu_suspensions','contenu_idees'))),
 ('six politiques, toutes en lecture (SELECT) pour authenticated', (select count(*) = 6 and bool_and(cmd = 'SELECT') and bool_and(roles = '{authenticated}') from pg_policies where schemaname = 'public' and tablename like 'contenu\_%')),
 ('aucune politique d''écriture', (select count(*) = 0 from pg_policies where schemaname = 'public' and tablename like 'contenu\_%' and cmd <> 'SELECT')),
 ('anon et PUBLIC : aucun droit de table', (select not exists (select 1 from information_schema.role_table_grants where table_schema = 'public' and table_name like 'contenu\_%' and grantee in ('anon', 'PUBLIC')))),
 ('authenticated : SELECT seulement', (select not exists (select 1 from information_schema.role_table_grants where table_schema = 'public' and table_name like 'contenu\_%' and grantee = 'authenticated' and privilege_type <> 'SELECT'))),
 ('service_role : lit et écrit les six tables', (select count(*) = 6 from pg_class c where c.relnamespace = 'public'::regnamespace and c.relname like 'contenu\_%' and c.relkind = 'r' and has_table_privilege('service_role', c.oid, 'select') and has_table_privilege('service_role', c.oid, 'insert') and has_table_privilege('service_role', c.oid, 'update'))),
 ('17 fonctions contenu_*', (select count(*) = 17 from pg_proc where pronamespace = 'public'::regnamespace and proname like 'contenu\_%')),
 ('12 fonctions exposées au seul service_role (ni anon, ni authenticated, ni public)', (select count(*) = 12 and bool_and(has_function_privilege('service_role', oid, 'execute') and not has_function_privilege('anon', oid, 'execute') and not has_function_privilege('authenticated', oid, 'execute')) from pg_proc where pronamespace = 'public'::regnamespace and proname like 'contenu\_%' and proname not in ('contenu_journal', 'contenu_lignes_garde', 'contenu_posts_garde', 'contenu_suspensions_garde', 'contenu_mesures_garde'))),
 ('5 fonctions privées : aucun exécuteur (ni anon, authenticated, service_role)', (select count(*) = 5 and bool_and(not has_function_privilege('service_role', oid, 'execute') and not has_function_privilege('anon', oid, 'execute') and not has_function_privilege('authenticated', oid, 'execute')) from pg_proc where pronamespace = 'public'::regnamespace and proname in ('contenu_journal', 'contenu_lignes_garde', 'contenu_posts_garde', 'contenu_suspensions_garde', 'contenu_mesures_garde'))),
 ('4 déclencheurs actifs (lignes, posts, suspensions, mesures)', (select count(*) = 4 and bool_and(tgenabled = 'O') from pg_trigger where tgname in ('contenu_lignes_garde', 'contenu_posts_garde', 'contenu_suspensions_garde', 'contenu_mesures_garde') and not tgisinternal)),
 ('cinq lignes L1-L5, aucune approuvée, aucune suspension', (select (select count(*) from public.contenu_lignes) = 5 and (select count(*) from public.contenu_lignes where approuvee_le is not null) = 0 and (select count(*) from public.contenu_suspensions) = 0)),
 ('campagnes ligne-l1..l5, une par ligne', (select count(distinct utm_campagne) = 5 and bool_and(utm_campagne = 'ligne-' || lower(id)) from public.contenu_lignes)),
 ('quatre comptes, un lien de bio par compte', (select count(*) = 4 and count(distinct lien_bio) = 4 and bool_and(lien_bio like 'https://prestiapp.fr/a/%') from public.contenu_comptes)),
 ('aucune publication, mesure, idée (zéro trace d''essai)', (select (select count(*) from public.contenu_posts) = 0 and (select count(*) from public.contenu_mesures) = 0 and (select count(*) from public.contenu_idees) = 0)),
 ('aucune décision d''essai 026-206 dans le bus', (select count(*) = 0 from ops.decisions where question like 'Essai 026-206%')),
 ('index de déduplication et d''unicité présents', (select count(*) = 3 from pg_indexes where schemaname = 'public' and indexname in ('contenu_posts_dedup', 'contenu_posts_externe', 'contenu_suspensions_active'))),
 ('contrainte : accord exigé pour publiable/publie', (select count(*) = 1 from pg_constraint where conname = 'contenu_posts_publiable_exige_accord')),
 ('migration enregistrée sous 0114_contenu', (select count(*) = 1 from supabase_migrations.schema_migrations where name = '0114_contenu'))
) t(label, ok) order by 1;
